EXTRA_CSS='#kilat{position:absolute;inset:0;z-index:11;background:radial-gradient(circle at 50% 50%,#fbe6ff,#e07bff);opacity:0;pointer-events:none}\n#dim{position:absolute;inset:0;z-index:8;background:#05030f;opacity:0;pointer-events:none}\n#split,#tl{position:absolute;left:60px;right:60px;z-index:13;opacity:0;pointer-events:none}\n#split{top:420px;display:flex;flex-wrap:wrap;gap:20px;justify-content:space-between}\n.cd{width:460px;height:290px;border-radius:28px;background:rgba(14,8,34,.88);border:3px solid rgba(243,185,255,.5);box-sizing:border-box;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px}\n.cd b{font:700 32px/1 var(--fm);letter-spacing:.08em;color:#fff}\n.cd span{font:800 50px/1 var(--fm);color:#fff;letter-spacing:.01em}\n.cd.s span{color:var(--ta)}\n.cd .ic{width:96px;height:96px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#7fc0ff,#1d5ba6 55%,#0d2b66);box-shadow:0 0 22px rgba(120,180,255,.5)}\n.cd svg{width:130px;height:96px}\n#diff{width:100%;text-align:center;margin-top:8px}\n#diff small{display:block;font:700 30px/1 var(--fm);letter-spacing:.1em;color:rgba(255,255,255,.8)}\n#diff strong{display:block;font:800 84px/1.1 var(--fj);color:var(--ta);text-shadow:0 0 24px var(--aks)}\n#spn{width:100%;text-align:center;margin:10px 0 0;font:600 26px/1.3 var(--fm);color:rgba(255,255,255,.7)}\n#tl{top:470px}\n.tr{margin-bottom:34px}\n.tr b{display:block;font:700 32px/1 var(--fm);letter-spacing:.08em;color:#fff;margin-bottom:14px}\n.bar{height:40px;border-radius:20px;background:rgba(255,255,255,.12);display:flex;overflow:hidden}\n.bar u{display:block;height:100%;background:linear-gradient(90deg,#8aa6ff,#f3e8ff)}\n.bar s{display:block;height:100%;background:var(--aks);box-shadow:0 0 22px var(--aks)}\n#tlT{font:700 36px/1.3 var(--fm);color:var(--ta);text-align:center;margin:18px 0 0}\n'
EXTRA_HTML='<div id="dim"></div><div id="kilat"></div>\n<div id="split"><div class="cd"><i class="ic"></i><b>DI BUMI</b><span id="clE">12:00:00.000</span></div><div class="cd s"><svg viewBox="0 0 130 96"><rect x="8" y="46" width="114" height="6" rx="3" fill="#cfd4dc"/><rect x="2" y="22" width="30" height="52" fill="#3a56b0" stroke="#c9a24a" stroke-width="3"/><rect x="98" y="22" width="30" height="52" fill="#3a56b0" stroke="#c9a24a" stroke-width="3"/><rect x="48" y="30" width="34" height="36" rx="12" fill="#e9eaf0" stroke="#d93cf5" stroke-width="4"/></svg><b>DI STASIUN</b><span id="clS">12:00:00.000</span></div><div id="diff"><small>SELISIH</small><strong id="dm">0,000 ms</strong></div><p id="spn">ilustrasi dipercepat · ±7 ms setelah ±6 bulan di orbit</p></div>\n<div id="tl"><div class="tr"><b>JAM BUMI</b><div class="bar"><u id="tlE" style="width:0"></u></div></div><div class="tr"><b>JAM ASTRONOT</b><div class="bar"><u id="tlA" style="width:0"></u><s id="tlG" style="width:0"></s></div></div></div>\n'
import json,re,sys
head=open('.head.html',encoding='utf-8').read()
head=head.replace('Kenapa nuklir bisa menghasilkan listrik?','Perjalanan ke masa depan itu nyata').replace('family=Overpass:wght@600;800;900&family=Overpass+Mono:wght@500;700','family=Space+Grotesk:wght@500;700&family=JetBrains+Mono:wght@500;700')
head=head.replace("--fj:'Overpass',sans-serif;--fm:'Overpass Mono',monospace","--fj:'Space Grotesk',sans-serif;--fm:'JetBrains Mono',monospace")
css="#seri{position:absolute;left:70px;top:88px;z-index:12;display:flex;align-items:center;gap:14px;opacity:0;font:700 29px/1 var(--fm);letter-spacing:.06em;color:#fff;text-shadow:0 2px 3px rgba(0,0,0,.8);padding:8px 24px 8px 12px;border-radius:44px;background:rgba(24,10,44,.5);border:2px solid rgba(243,185,255,.6)}\n"
head=head.replace('</style>',css+EXTRA_CSS+'</style>',1)
svg='<div id="seri"><svg viewBox="0 0 64 64" width="56" height="56"><defs><radialGradient id="brs" cx=".35" cy=".3" r=".9"><stop offset="0" stop-color="#ffe9a0"/><stop offset=".55" stop-color="#c9993a"/><stop offset="1" stop-color="#7a5418"/></radialGradient></defs><rect x="28" y="1" width="8" height="9" rx="2" fill="url(#brs)"/><circle cx="32" cy="36" r="26" fill="url(#brs)"/><circle cx="32" cy="36" r="20" fill="#f6efd8"/><g class="wh"><rect x="31" y="22" width="2.4" height="14" rx="1" fill="#2a1c10"/></g><g class="wm"><rect x="31.2" y="27" width="1.8" height="9" rx="1" fill="#2a1c10"/></g><circle cx="32" cy="36" r="2" fill="#7a5418"/></svg><span>PERJALANAN WAKTU · EP 3</span></div>'
head=head.replace('<div id="jejak"></div>','<div id="jejak"></div>\n<div id="rpm"></div>\n'+svg+EXTRA_HTML)
a=open('.st_a.js',encoding='utf-8').read()
s=open('.script.js',encoding='utf-8').read();tex=s[s.index('/* ---------- TEKSTUR (canvas)'):s.index('const salin')]
b=open('.bs_head.js',encoding='utf-8').read()+open('.st_b.js',encoding='utf-8').read();d=open('.st_d.js',encoding='utf-8').read()
tts=json.load(open(sys.argv[1] if len(sys.argv)>1 else '.tts_st.json',encoding='utf-8'));assert len(tts)==7
d=d.replace('__TTS__',json.dumps(tts,ensure_ascii=False))
open('stasiun/scene.html','w',encoding='utf-8').write(head+a+tex+b+d);print('ok')
